extern "C"
const char* getResource(const char* path, int *length)
{
	FileContent *fc = fileContent;
	while (fc->name)
	{
		if (!strcmp(fc->name, path))
		{
			if (length)
				*length = fc->length;
			return fc->bytes;
		}
		++fc;
	}
	return 0;
}

int getResourceCount()
{
    return static_cast<int>(sizeof(fileContent) / (sizeof(FileContent)) - 1);
}

const char* getResourceName(int index)
{
    return fileContent[index].name;
}
